<script lang="ts">import type {Project} from '$lib/model';import {databaseState} from '$lib/database/store';import {previewWebsite} from '$lib/websites/store';export let project:Project;let error='',notice='';$: linked=$databaseState.databases.find(d=>d.project===project.id);function preview(){try{previewWebsite(project.id);error='';notice='Entry point found. Readiness preview saved; nothing is published.';}catch(e){error=e instanceof Error?e.message:'Readiness preview failed.';}}</script>
<section class="card stack"><div class="row between wrap"><div><h3>{project.framework==='WordPress'?'WordPress setup':'Website setup'}</h3><p class="subtitle">Website management · development preview</p></div><a class="btn secondary small" href="/websites">All websites</a></div>{#if project.framework==='WordPress'}<div class="summary-list"><div><span>Operation</span><strong>{project.websiteSetup?.mode==='migrate'?'Migration':project.websiteSetup?'Fresh install':'Uploaded source'}</strong></div><div><span>Database</span>{#if linked}<a class="link-btn" href={'/databases/'+linked.id}>{linked.name} · {linked.engine}</a>{:else}<a class="link-btn" href={'/projects/'+project.id+'/database'}>Connect database</a>{/if}</div><div><span>WordPress administrator</span><strong>Installation pending</strong></div></div>{#if project.websiteSetup?.mode==='migrate'}<p class="subtitle">{project.websiteSetup.sample?'Sample migration selected.':('Selected backups: '+project.websiteSetup.archive?.name+' and '+project.websiteSetup.sql?.name+'.')} No backup contents have been restored.</p>{/if}<small>WordPress, PHP runtime, database credentials and wp-admin are unavailable until actual installation.</small>{:else if ['Static website','PHP'].includes(project.framework)}<p class="subtitle">Check the website entry point before publishing. This does not start a web server.</p><div><button class="btn primary" on:click={preview}>Check publishing readiness</button></div>{#if project.websitePreview}<div class="summary-list"><div><span>Last readiness preview</span><strong>{new Date(project.websitePreview.at).toLocaleString()}</strong></div><div><span>Publishing directory</span><strong class="native-path">{project.websitePreview.directory}</strong></div></div>{/if}{:else}<p class="subtitle">This website requires an application build and runtime configuration before publication.</p>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p class="subtitle" role="status">{notice}</p>{/if}<div class="row wrap"><a class="btn secondary small" href={'/projects/'+project.id+'/files'}>Website files</a><a class="btn secondary small" href={'/projects/'+project.id+'/deployments'}>Deployment status</a></div></section>
